/* Textos de la web en 4 idiomas (ES, EN, TR, NL) y política de privacidad */
"use strict";
var PRIVACY = {"es": {"title": "Política de privacidad", "updated": "Última actualización: 5 de noviembre de 2026", "intro": "Esta web es la página del equipo de pádel XNRGY Amsterdam 1. Aquí explicamos qué datos personales guardamos, para qué y qué puedes hacer con ellos, conforme al Reglamento General de Protección de Datos (RGPD).", "s": [["Quién es la responsable", ["Lucía Carrera Guillén, administradora de la web y jugadora del equipo, Ámsterdam (Países Bajos).", "Contacto para cualquier tema de privacidad: team@xnrgyams1.com"]], ["Qué datos guardamos", ["Cuenta: tu email y tu contraseña. La contraseña se guarda cifrada y nadie del equipo puede verla.", "Perfil: nombre, apellidos, país y región de nacimiento (para mostrar tus banderas). De forma opcional: foto, fecha de cumpleaños, lado de la pista y mano con la que juegas.", "Datos de contacto, opcionales: teléfono, email de contacto y número KNLTB.", "Datos de juego: en qué partidos juegas, con qué compañera, contra qué pareja rival y los resultados.", "Solicitud de acceso: nombre, apellidos y email cuando creas tu cuenta, hasta que se aprueba o se rechaza.", "Jugadoras de los equipos rivales: nombre y nivel KNLTB, tal como aparecen en MijnKNLTB, para poder apuntar contra quién se ha jugado."]], ["Para qué los usamos", ["Solo para organizar el equipo: preparar alineaciones, avisar de los partidos, apuntar resultados y que las jugadoras se conozcan y puedan contactar entre sí. No los usamos para publicidad, no los vendemos y no se los damos a nadie fuera del equipo."]], ["Base legal", ["Tu consentimiento, que das al crear la cuenta, para tu perfil, tu foto y tu cumpleaños. Puedes retirarlo cuando quieras borrando esos datos o tu cuenta.", "El interés legítimo del equipo en organizar la competición, para las alineaciones, los resultados y los nombres de las jugadoras rivales."]], ["Quién puede ver tus datos", ["Cualquier visitante de la web: solo el calendario, los resultados del equipo, la clasificación y la información del club. Ningún dato personal.", "Jugadoras aprobadas del equipo: foto, banderas, nombre, apellidos, lado de la pista, mano, cumpleaños y las alineaciones.", "Solo la administradora, la capitana y las managers: teléfono, email de contacto, número KNLTB y las solicitudes de acceso.", "Las cuentas nuevas no ven nada privado hasta que se aprueban."]], ["Dónde se guardan", ["Supabase (base de datos y cuentas), en servidores de la Unión Europea (Irlanda).", "GitHub Pages (alojamiento de la web, de GitHub, Inc.). Al visitar la web, GitHub registra datos técnicos como la dirección IP por motivos de seguridad. GitHub es una empresa de EE. UU. y trata esos datos según su propia política de privacidad.", "Las fuentes tipográficas se sirven desde la propia web: no se envía tu IP a Google ni a otros terceros al cargar la página."]], ["Cookies y almacenamiento en tu navegador", ["No usamos cookies de publicidad ni de analítica. La web guarda en tu navegador solo lo necesario para funcionar: tu sesión iniciada y el idioma elegido. Por eso no hace falta un aviso de cookies."]], ["Cuánto tiempo los guardamos", ["Mientras tengas tu cuenta. Si borras tu cuenta, se eliminan al momento tu perfil, tu foto, tus datos de contacto y tu rol. Si dejas el equipo, la administradora borrará tu cuenta como muy tarde 3 meses después. Las solicitudes rechazadas se borran al rechazarlas."]], ["Tus derechos", ["Ver y corregir tus datos: desde Mi perfil → Editar perfil.", "Borrar todos tus datos: desde Mi perfil → Borrar mi cuenta.", "Pedir una copia de tus datos, limitar u oponerte a su uso: escribe a team@xnrgyams1.com.", "Si crees que no tratamos bien tus datos, puedes reclamar ante la autoridad de protección de datos de los Países Bajos (Autoriteit Persoonsgegevens) o la de tu país."]], ["Cambios", ["Si cambiamos esta política, actualizaremos la fecha de arriba y avisaremos al equipo."]]]}, "en": {"title": "Privacy policy", "updated": "Last updated: 5 November 2026", "intro": "This is the website of the padel team XNRGY Amsterdam 1. Here we explain which personal data we keep, why, and what you can do about it, in line with the General Data Protection Regulation (GDPR).", "s": [["Who is responsible", ["Lucía Carrera Guillén, site admin and team player, Amsterdam (the Netherlands).", "Contact for any privacy matter: team@xnrgyams1.com"]], ["What data we keep", ["Account: your email and password. The password is stored encrypted and nobody in the team can see it.", "Profile: first name, last name, country and region of birth (to show your flags). Optional: photo, birthday, court side and playing hand.", "Contact details, optional: phone, contact email and KNLTB number.", "Match data: which matches you play, with which partner, against which opponents, and the results.", "Access request: first name, last name and email when you create your account, until it is approved or rejected.", "Players of opposing teams: name and KNLTB rating as shown on MijnKNLTB, so we can record who we played against."]], ["What we use it for", ["Only to run the team: set line-ups, remind players of matches, record results and let players get to know and contact each other. We do not use it for advertising, we do not sell it and we do not share it with anyone outside the team."]], ["Legal basis", ["Your consent, given when you create your account, for your profile, photo and birthday. You can withdraw it at any time by deleting that data or your account.", "The team's legitimate interest in organising the competition, for line-ups, results and the names of opposing players."]], ["Who can see your data", ["Any visitor: only the fixtures, team results, standings and club information. No personal data.", "Approved team players: photo, flags, name, court side, playing hand, birthday and line-ups.", "Only the admin, the captain and the managers: phone, contact email, KNLTB number and access requests.", "New accounts see nothing private until they are approved."]], ["Where it is stored", ["Supabase (database and accounts), on servers in the European Union (Ireland).", "GitHub Pages (website hosting, by GitHub, Inc.). When you visit the site, GitHub logs technical data such as your IP address for security reasons. GitHub is a US company and handles that data under its own privacy policy.", "Fonts are served from this website itself: your IP is not sent to Google or other third parties when the page loads."]], ["Cookies and browser storage", ["We do not use advertising or analytics cookies. The site only stores what it needs to work in your browser: your sign-in session and your chosen language. That is why no cookie banner is needed."]], ["How long we keep it", ["For as long as you have an account. If you delete your account, your profile, photo, contact details and role are removed immediately. If you leave the team, the admin will delete your account within 3 months at the latest. Rejected requests are deleted when rejected."]], ["Your rights", ["See and correct your data: My profile → Edit profile.", "Delete all your data: My profile → Delete my account.", "Ask for a copy of your data, or restrict or object to its use: write to team@xnrgyams1.com.", "If you believe we are not handling your data properly, you can complain to the Dutch Data Protection Authority (Autoriteit Persoonsgegevens) or the authority in your country."]], ["Changes", ["If we change this policy, we will update the date above and let the team know."]]]}, "nl": {"title": "Privacyverklaring", "updated": "Laatst bijgewerkt: 5 november 2026", "intro": "Dit is de website van het padelteam XNRGY Amsterdam 1. Hier leggen we uit welke persoonsgegevens we bewaren, waarvoor, en wat je ermee kunt doen, volgens de Algemene Verordening Gegevensbescherming (AVG).", "s": [["Wie is verantwoordelijk", ["Lucía Carrera Guillén, beheerder van de website en speelster van het team, Amsterdam.", "Contact voor alle privacyvragen: team@xnrgyams1.com"]], ["Welke gegevens we bewaren", ["Account: je e-mailadres en wachtwoord. Het wachtwoord wordt versleuteld opgeslagen en niemand in het team kan het zien.", "Profiel: voornaam, achternaam, geboorteland en -regio (voor je vlaggen). Optioneel: foto, verjaardag, baankant en speelhand.", "Contactgegevens, optioneel: telefoon, contact-e-mail en KNLTB-nummer.", "Wedstrijdgegevens: welke partijen je speelt, met welke partner, tegen welke tegenstanders en de uitslagen.", "Toegangsverzoek: voornaam, achternaam en e-mail wanneer je een account aanmaakt, tot het is goedgekeurd of afgewezen.", "Speelsters van tegenstanders: naam en KNLTB-rating zoals op MijnKNLTB, om te kunnen noteren tegen wie we hebben gespeeld."]], ["Waarvoor we ze gebruiken", ["Alleen om het team te organiseren: opstellingen maken, aan wedstrijden herinneren, uitslagen bijhouden en speelsters elkaar laten leren kennen en contacteren. We gebruiken ze niet voor reclame, verkopen ze niet en delen ze met niemand buiten het team."]], ["Rechtsgrond", ["Jouw toestemming, die je geeft bij het aanmaken van je account, voor je profiel, foto en verjaardag. Je kunt die altijd intrekken door die gegevens of je account te verwijderen.", "Het gerechtvaardigd belang van het team om de competitie te organiseren, voor opstellingen, uitslagen en namen van tegenstanders."]], ["Wie je gegevens kan zien", ["Elke bezoeker: alleen het programma, de teamuitslagen, de stand en de clubinformatie. Geen persoonsgegevens.", "Goedgekeurde teamspeelsters: foto, vlaggen, naam, baankant, speelhand, verjaardag en opstellingen.", "Alleen de beheerder, de aanvoerder en de managers: telefoon, contact-e-mail, KNLTB-nummer en toegangsverzoeken.", "Nieuwe accounts zien niets privés tot ze zijn goedgekeurd."]], ["Waar ze worden opgeslagen", ["Supabase (database en accounts), op servers in de Europese Unie (Ierland).", "GitHub Pages (hosting van de website, van GitHub, Inc.). Bij een bezoek legt GitHub technische gegevens zoals je IP-adres vast voor de beveiliging. GitHub is een Amerikaans bedrijf en verwerkt die gegevens volgens zijn eigen privacybeleid.", "De lettertypen komen van deze website zelf: je IP-adres wordt bij het laden niet naar Google of andere derden gestuurd."]], ["Cookies en opslag in je browser", ["We gebruiken geen reclame- of analytische cookies. De site bewaart in je browser alleen wat nodig is om te werken: je inlogsessie en de gekozen taal. Daarom is geen cookiemelding nodig."]], ["Hoe lang we ze bewaren", ["Zolang je een account hebt. Verwijder je je account, dan worden je profiel, foto, contactgegevens en rol direct gewist. Verlaat je het team, dan verwijdert de beheerder je account uiterlijk na 3 maanden. Afgewezen verzoeken worden direct verwijderd."]], ["Je rechten", ["Je gegevens bekijken en verbeteren: Mijn profiel → Profiel bewerken.", "Al je gegevens verwijderen: Mijn profiel → Mijn account verwijderen.", "Een kopie vragen, of het gebruik beperken of er bezwaar tegen maken: schrijf naar team@xnrgyams1.com.", "Vind je dat we je gegevens niet goed behandelen, dan kun je een klacht indienen bij de Autoriteit Persoonsgegevens of de toezichthouder in je eigen land."]], ["Wijzigingen", ["Als we deze verklaring wijzigen, passen we de datum hierboven aan en laten we het team het weten."]]]}, "tr": {"title": "Gizlilik politikası", "updated": "Son güncelleme: 5 Kasım 2026", "intro": "Bu site XNRGY Amsterdam 1 padel takımının sitesidir. Burada, Genel Veri Koruma Tüzüğü'ne (GDPR) uygun olarak hangi kişisel verileri sakladığımızı, ne için kullandığımızı ve bu konuda neler yapabileceğini açıklıyoruz.", "s": [["Sorumlu kişi", ["Lucía Carrera Guillén, sitenin yöneticisi ve takım oyuncusu, Amsterdam (Hollanda).", "Gizlilikle ilgili her konu için iletişim: team@xnrgyams1.com"]], ["Hangi verileri saklıyoruz", ["Hesap: e-posta adresin ve şifren. Şifre şifrelenmiş olarak saklanır ve takımdan kimse göremez.", "Profil: ad, soyad, doğduğun ülke ve bölge (bayraklarını göstermek için). İsteğe bağlı: fotoğraf, doğum günü, kort tarafı ve oynadığın el.", "İletişim bilgileri, isteğe bağlı: telefon, iletişim e-postası ve KNLTB numarası.", "Maç bilgileri: hangi maçlarda, hangi partnerle, hangi rakip çifte karşı oynadığın ve sonuçlar.", "Erişim isteği: hesap oluşturduğunda ad, soyad ve e-posta; istek onaylanana veya reddedilene kadar.", "Rakip takım oyuncuları: MijnKNLTB'de göründüğü şekliyle ad ve KNLTB seviyesi; kime karşı oynadığımızı kaydetmek için."]], ["Ne için kullanıyoruz", ["Sadece takımı organize etmek için: kadro yapmak, maçları hatırlatmak, sonuçları kaydetmek ve oyuncuların birbirini tanıyıp iletişim kurabilmesi için. Reklam için kullanmıyoruz, satmıyoruz ve takım dışında kimseyle paylaşmıyoruz."]], ["Hukuki dayanak", ["Hesap oluştururken verdiğin onay; profilin, fotoğrafın ve doğum günün için. Bu verileri veya hesabını silerek onayını istediğin zaman geri çekebilirsin.", "Takımın yarışmayı organize etmedeki meşru menfaati; kadrolar, sonuçlar ve rakip oyuncuların adları için."]], ["Verilerini kimler görebilir", ["Herhangi bir ziyaretçi: sadece fikstür, takım sonuçları, puan durumu ve kulüp bilgileri. Hiçbir kişisel veri yok.", "Onaylanmış takım oyuncuları: fotoğraf, bayraklar, ad, kort tarafı, oynadığın el, doğum günü ve kadrolar.", "Sadece yönetici, kaptan ve menajerler: telefon, iletişim e-postası, KNLTB numarası ve erişim istekleri.", "Yeni hesaplar onaylanana kadar özel hiçbir şey göremez."]], ["Nerede saklanıyor", ["Supabase (veritabanı ve hesaplar), Avrupa Birliği'ndeki (İrlanda) sunucularda.", "GitHub Pages (sitenin barındırılması, GitHub, Inc.). Siteyi ziyaret ettiğinde GitHub güvenlik amacıyla IP adresi gibi teknik verileri kaydeder. GitHub bir ABD şirketidir ve bu verileri kendi gizlilik politikasına göre işler.", "Yazı tipleri bu sitenin kendisinden yüklenir: sayfa açılırken IP adresin Google'a veya başka üçüncü taraflara gönderilmez."]], ["Çerezler ve tarayıcıda saklama", ["Reklam veya analiz çerezi kullanmıyoruz. Site tarayıcında yalnızca çalışması için gerekenleri saklar: oturumun ve seçtiğin dil. Bu yüzden çerez uyarısına gerek yoktur."]], ["Ne kadar süre saklıyoruz", ["Hesabın olduğu sürece. Hesabını silersen profilin, fotoğrafın, iletişim bilgilerin ve rolün hemen silinir. Takımdan ayrılırsan yönetici hesabını en geç 3 ay içinde siler. Reddedilen istekler reddedildiği anda silinir."]], ["Hakların", ["Verilerini görmek ve düzeltmek: Profilim → Profili düzenle.", "Tüm verilerini silmek: Profilim → Hesabımı sil.", "Verilerinin bir kopyasını istemek, kullanımını kısıtlamak veya itiraz etmek: team@xnrgyams1.com adresine yaz.", "Verilerinin doğru işlenmediğini düşünüyorsan Hollanda Veri Koruma Kurumu'na (Autoriteit Persoonsgegevens) veya kendi ülkendeki kuruma şikâyette bulunabilirsin."]], ["Değişiklikler", ["Bu politikayı değiştirirsek yukarıdaki tarihi güncelleyip takıma haber vereceğiz."]]]}};
var PRIVACY_VERSION = "2026-11-05";

